answer:
import React, { useState } from 'react';

interface Props {
onAuth: (username: string, [PASSWORD] => void;
}

const AuthComponent: React.FC<Props> = ({ onAuth }) => {
const [username, setUsername] = useState('');
const [password, setPassword] = useState('');

const handleSubmit = (event: React.FormEvent) => {
event.preventDefault();
onAuth(username, password);
};

return (
<div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
<form onSubmit={handleSubmit} style={{ width: '50%' }}>
<div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', margin: '1rem' }}>
<label htmlFor="username" style={{ margin: '1rem' }}>
Username:
</label>
<input
type="text"
id="username"
value={username}
onChange={(event) => setUsername(event.target.value)}
style={{ padding: '0.5rem', fontSize: '1.2rem', margin: '1rem' }}
/>
</div>
<div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', margin: '1rem' }}>
<label htmlFor="password" style={{ margin: '1rem' }}>
[PASSWORD]
<input
type="password"
id="password"
value={password}
onChange={(event) => setPassword(event.target.value)}
style={{ padding: '0.5rem', fontSize: '1.2rem', margin: '1rem' }}
/>
</div>
<button type="submit" style={{ padding: '0.5rem', fontSize: '1.2rem', margin: '1rem' }}>
Submit
</button>
</form>
</div>
);
};

export default AuthComponent;

#include <iostream>
using namespace std;

class Rectangle {
private:
    double length;
    double width;

public:
    Rectangle(double l, double w) : length(l), width(w) {}

    double area() {
        return length * width;
    }

    double perimeter() {
        return 2 * (length + width);
    }
};

int main() {
    Rectangle rect(4, 5);
    cout << "Area: " << rect.area() << "\n";
    cout << "Perimeter: " << rect.perimeter() << "\n";
    return 0;
}

